def _final_flush(self) -> None:
    # Drain whatever the OS has already buffered on the PTY, so that output
    # produced right up to shutdown is not lost.  Termination is driven by
    # an observable data condition -- the PTY reporting no more data ready
    # (``select`` not ready) or a read yielding EOF/empty -- rather than by
    # an arbitrary wall-clock deadline.  Each ``select`` call waits briefly
    # for the next chunk; when none arrives the buffer is empty and we stop.
    fd = getattr(self._child, "child_fd", None)
    if fd is None:
        return
    while True:
        try:
            ready, _, _ = select.select([fd], [], [], 0.05)
        except (OSError, ValueError):
            return
        if not ready:
            return
        try:
            chunk = os.read(fd, 65536)
        except (OSError, ValueError):
            return
        if not chunk:
            return
        text = chunk.decode(self._encoding, errors="replace")
        with self._buffer_lock:
            self._buffer.append(text)

